WHERE tenant_id = #{tenantId}
  AND event_id = #{eventId}
LIMIT 1

mapper.insert:
INSERT INTO ai_business_event_sequence (
    aggregate_key, tenant_id, object_code, record_id, last_sequence,
    create_time, update_time
) VALUES (
    #{aggregateKey}, #{tenantId}, #{objectCode}, #{recordId}, 1,
    #{now}, #{now}
)
ON DUPLICATE KEY UPDATE
    last_sequence = last_sequence + 1,
    update_time = VALUES(update_time)

mapper.select:
SELECT last_sequence
FROM ai_business_event_sequence
WHERE tenant_id = #{tenantId}
  AND aggregate_key = #{aggregateKey}
FOR UPDATE

mapper.update:
UPDATE ai_business_event_outbox
SET delivery_status = 'DEAD',
    next_retry_time = NULL,
    lock_owner = NULL,
    lock_time = NULL,
    error_type = 'LeaseExpiredAfterRetryLimit',
    update_time = #{now}
WHERE tenant_id = #{tenantId}
  AND id = #{id}
  AND delivery_status = 'PROCESSING'
  AND retry_count >= #{maxRetryCount}
  AND (lock_time IS NULL OR lock_time <= #{staleBefore})

mapper.select:
SELECT 
FROM ai_business_event_outbox
WHERE tenant_id = #{tenantId}
  AND id = #{id}
LIMIT 1

mapper.update:
UPDATE ai_business_event_outbox
SET delivery_status = 'DELIVERED',
    next_retry_time = NULL,
    lock_owner = NULL,
    lock_time = NULL,
    error_type = NULL,
    delivered_time = #{now},
    update_time = #{now}
WHERE tenant_id = #{outbox.tenantId}
  AND id = #{outbox.id}
  AND delivery_status = 'PROCESSING'
  AND lock_owner = #{outbox.lockOwner}

UPDATE ai_business_event_outbox
SET delivery_status = #{status},
    next_retry_time = #{nextRetryTime},
    lock_owner = NULL,
    lock_time = NULL,
    error_type = #{errorType},
    update_time = #{now}
WHERE tenant_id = #{outbox.tenantId}
  AND id = #{outbox.id}
  AND delivery_status = 'PROCESSING'
  AND lock_owner = #{outbox.lockOwner}
